type Tarefa = {
  id: number
  titulo: string
  concluida: boolean
}

type Estado = 'todas' | 'abertas' | 'concluidas'

type Filtro = {
  estado: string
  termo?: string
}

const estados: ReadonlyArray<string> = ['todas', 'abertas', 'concluidas']

const ehEstado = (valor: string): valor is Estado => estados.includes(valor)

const casaEstado = (estado: Estado, tarefa: Tarefa): boolean => {
  if (estado === 'abertas') return !tarefa.concluida
  if (estado === 'concluidas') return tarefa.concluida
  return true
}

const normalizarTermo = (termo: string | undefined): string | undefined => {
  if (termo === undefined) return undefined
  const limpo = termo.trim().toLowerCase()
  return limpo === '' ? undefined : limpo
}

export const filtrarTarefas = (tarefas: Tarefa[], filtro: Filtro): Tarefa[] => {
  const estado = filtro.estado
  if (!ehEstado(estado)) throw new Error('Estado inválido')

  const termo = normalizarTermo(filtro.termo)

  return tarefas.filter(
    tarefa =>
      casaEstado(estado, tarefa) &&
      (termo === undefined || tarefa.titulo.toLowerCase().includes(termo))
  )
}
